```javascript
async function retryFetch(fn, { times = 3, delay = 50 } = {}) {
  let last;
  for (let i = 0; i < times; i++) {
    try {
      const res = await fn();
      if (res && typeof res.status === 'number' && res.status >= 500) {
        last = new Error(`status ${res.status}`);
        last.retryable = true;
      } else {
        return res;
      }
    } catch (err) {
      last = err;
      if (!err || err.retryable !== true) throw err;
    }
    if (i < times - 1) await new Promise((r) => setTimeout(r, delay));
  }
  throw last;
}
```

Non-retryable errors fail immediately. 4xx responses are returned, not retried.
